def match_parens(lst):
    def is_good(s):
        balance = 0
        for char in s:
            balance += 1 if char == '(' else -1
            if balance < 0: return False
        return balance == 0

    s1, s2 = lst
    if is_good(s1 + s2) or is_good(s2 + s1):
        return 'Yes'
    return 'No'
