from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    res = []
    for group in paren_string.split():
        depth = 0
        max_d = 0
        for char in group:
            if char == '(':
                depth += 1
                if depth > max_d: max_d = depth
            else:
                depth -= 1
        res.append(max_d)
    return res
```

