def largest_prime_factor(n: int):
    max_f = 1
    d = 2
    while d * d <= n:
        if n % d == 0:
            max_f = d
            while n % d == 0:
                n //= d
        d += 1
    if n > 1:
        return max(max_f, n)
    return max_f
